@startuml
title Partial Bill Payment Sequence

actor Customer
participant "Web/Mobile App" as App
participant "Billing Service" as Billing
participant "Payment Service" as Pay
database "Payment Gateway" as Gateway
database "Billing DB" as BillDB

Customer -> App: Open bill details
App -> Billing: GET /bills/{billId}
Billing -> BillDB: Query bill\n(amountDue, status, history)
BillDB --> Billing: Bill details
Billing --> App: Bill details
App --> Customer: Display bill and\npartial payment option

Customer -> App: Enter partial amount\nand payment method\nthen confirm payment
App -> Billing: POST /bills/{billId}/payments\n{amount, method}
Billing -> BillDB: Validate bill status\nand remaining balance
BillDB --> Billing: Validation result

alt Partial amount valid and bill payable
    Billing -> Pay: Create payment request\n{billId, amount, method}
    Pay -> Gateway: Authorize payment\n{amount, card/bank details}
    Gateway --> Pay: Authorization result

    alt Authorization successful
        Pay --> Billing: Payment success\n{paymentId, amount}
        Billing -> BillDB: Record partial payment\nUpdate remaining balance\nUpdate bill status (e.g. PARTIALLY_PAID)
        BillDB --> Billing: Update OK
        Billing --> App: 200 OK\n{paymentStatus: SUCCESS,\nremainingBalance}
        App --> Customer: Show payment confirmation\nand updated remaining balance
    else Authorization failed
        Pay --> Billing: Payment failed\n{reason}
        Billing --> App: 402 Payment Required\n{paymentStatus: FAILED,\nreason}
        App --> Customer: Show payment failure\nand error message
    end
else Invalid partial amount\n(e.g. > remaining balance or <= 0)
    Billing --> App: 400 Bad Request\n{error: "Invalid partial amount"}
    App --> Customer: Show validation error
end

@enduml

