@startuml
title Locate ALFRED User

actor MedicalCaregiver as CG
participant "Mobile App" as App
participant "Backend Service" as BE
database "User Location DB" as DB
participant "ALFRED Device" as Dev
participant "Location Provider\n(GPS/WiFi/Cell)" as Loc

== Start Location Request ==
CG -> App: Request user location
App -> BE: POST /location/request\n{ userId }

== Retrieve Last Known Location ==
BE -> DB: Query last known location\nfor userId
DB --> BE: Last known location\n(if available)

alt Last known location is recent
  BE -> App: 200 OK\n{ location, timestamp, source="cached" }
  App --> CG: Display user location\n(on map)
else No recent location or none found
  == Live Location Acquisition ==
  BE -> Dev: Request current location\n{ userId }
  Dev -> Loc: Get current location
  Loc --> Dev: Current coordinates\n{ lat, lon, accuracy }
  Dev --> BE: Current location\n{ lat, lon, accuracy, timestamp }
  BE -> DB: Store location\n{ userId, lat, lon, timestamp }
  BE -> App: 200 OK\n{ location, timestamp, source="live" }
  App --> CG: Display user location\n(on map)
end

== Optional: Error Handling ==
else Device unreachable / error
  BE -> App: 503 Service Unavailable\n{ error }
  App --> CG: Show error message\n"Unable to locate user"
end

@enduml

