```plantuml
@startuml EAD_Upload_Sequence_Diagram

actor Archivist

participant "Frontend" as FE
participant "Backend API" as BE
participant "File Upload Service" as FUS
participant "EAD Validation Service" as EVS
participant "Storage Service" as SS
participant "Database" as DB

autonumber "<b>"

Archivist -> FE : 1. Select EAD file (local file picker)
Archivist -> FE : 2. Click "Upload EAD" button

FE -> BE : 3. POST /api/ead/upload\n{file, metadata}
BE -> FUS : 4. Upload file to temporary storage
FUS --> BE : 5. Temporary file URL\n{status: success/failure}

alt Upload Successful
    BE -> EVS : 6. Validate EAD structure\n{schema, metadata checks}
    EVS --> BE : 7. Validation results\n{status: valid/invalid, errors}

    alt Validation Passed
        BE -> SS : 8. Move file to permanent storage\n{path: /archives/ead/[ID]}
        SS --> BE : 9. Storage confirmation\n{status: success}

        BE -> DB : 10. Record metadata\n{eadId, filename, uploadDate, archivistId}
        DB --> BE : 11. Confirmation

        BE --> FE : 12. Upload success response\n{status: 200, eadId}

    else Validation Failed
        BE --> FE : 13. Return validation errors\n{status: 400, errorDetails}
    end

else Upload Failed
    BE --> FE : 14. Return upload failure\n{status: 500, errorDetails}
end

@enduml
```

