```plantuml
@startuml
actor RepositoryManager

participant "UI Layer" as UI
participant "MetadataService" as MS
participant "MetadataRepository" as MR
participant "ValidationService" as VS
participant "StorageService" as SS

RepositoryManager -> UI : Clicks "Add Name Relation" (UI: Dropdown: Creator/Source/Subject)
UI -> MS : Posts {relationType: "Creator/Source/Subject", name: "Name", identifier: "ID"}
MS -> VS : Validates input (name, relationType)
alt Input valid
    VS --> MS : Returns {isValid: true}
    MS -> MR : Saves relation to metadata {repositoryID: "ID", relationType: relationType, name: name}
    MR --> MS : Returns {success: true}
    MS -> SS : Updates repository metadata
    SS --> MS : Returns {status: "updated"}
    MS --> UI : Notifies success
    UI --> RepositoryManager : Shows confirmation (e.g., "Name added as Creator")
else Input invalid
    VS --> MS : Returns {isValid: false, errors: ["Error1", "Error2"]}
    MS --> UI : Returns validation errors
    UI --> RepositoryManager : Displays error messages
end
@enduml
```

